// Des: Tests contact store: phone merge, forget, drop private, exports
// Flo: temp db > save contacts > assert rows
// I/O: Carz structs > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const cstr = @import("st-carz-stor.zig"); const stor = @import("st-cont-stor.zig"); const typz = @import("pa-carz-type.zig");
const NOWZ: i64 = 1_795_600_000_000;
fn scal(dbzz: *sqli.Dbzz, sqlz: [:0]const u8) !i64 { var stmt = try dbzz.prep(sqlz); defer stmt.fini(); _ = try stmt.step(); return stmt.colzIntz(0); }
fn mkzz(urlz: []const u8, cnam: []const u8, phon: []const u8, sell: []const u8) typz.Carz { return .{ .urlz = urlz, .site = "x.vn", .make = "Toyota", .year = 2020, .cond = "used", .pric = 500_000_000, .prov = "Hà Nội", .cnam = cnam, .phon = phon, .sell = sell, .cadd = "1 Phố Huế, Hà Nội", .cdes = "Bán xe đẹp, giá tốt", .cmai = "a@b.vn" }; }
fn opnz(tmpz: *std.testing.TmpDir, buff: *[160]u8) !sqli.Dbzz { const dirz = try std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); return inde.pageOpen(std.testing.allocator, std.testing.io, dirz); }
test "same full phone on two sites is one contact, best fields win, a masked phone never beats a full one" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var dbzz = try opnz(&tmpz, &buff); defer dbzz.close(); var stoz = try cstr.storOpen(&dbzz, NOWZ); _ = try cstr.carzSave(&stoz, mkzz("https://x.vn/a-1", "", "", ""), "h", NOWZ); _ = try cstr.carzSave(&stoz, mkzz("https://y.vn/b-2", "", "", ""), "h", NOWZ); try stor.contSave(&stoz, mkzz("https://x.vn/a-1", "Lê Văn A", "0966 353 678", "private"), NOWZ, true); var twoz = mkzz("https://y.vn/b-2", "Showroom Minh Auto", "0966.353.678", "dealer"); twoz.cadd = ""; twoz.site = "y.vn"; try stor.contSave(&stoz, twoz, NOWZ + 1000, true); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM cont;")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM cont WHERE kind='dealer' AND name='Showroom Minh Auto' AND addr='1 Phố Huế, Hà Nội' AND phon='0966353678' AND mask=0 AND lasz=1795600001000 AND fors=1795600000000;")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM carz WHERE cont<>'';")); try stor.contSave(&stoz, mkzz("https://x.vn/a-1", "", "0966 353 ***", "private"), NOWZ + 2000, true); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM cont WHERE phon='0966353678' AND mask=0;")); }
test "masked phone and no phone: contacts are kept apart by name and address, nothing is saved for an empty seller" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var dbzz = try opnz(&tmpz, &buff); defer dbzz.close(); var stoz = try cstr.storOpen(&dbzz, NOWZ); try stor.contSave(&stoz, mkzz("https://x.vn/a-1", "An", "0922 079 ***", "private"), NOWZ, true); try stor.contSave(&stoz, mkzz("https://x.vn/a-2", "Binh", "", "private"), NOWZ, true); try stor.contSave(&stoz, mkzz("https://x.vn/a-3", "An", "0922 079 ***", "private"), NOWZ, true); var empz = mkzz("https://x.vn/a-4", "", "", ""); empz.cadd = ""; empz.cmai = ""; try stor.contSave(&stoz, empz, NOWZ, true); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM cont;")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT mask FROM cont WHERE name='An';")); }
test "cont_priv_enab off: a private seller keeps only the phone hash, a dealer stays in full" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var dbzz = try opnz(&tmpz, &buff); defer dbzz.close(); var stoz = try cstr.storOpen(&dbzz, NOWZ); try stor.contSave(&stoz, mkzz("https://x.vn/a-1", "Lê Văn A", "0966 353 678", "private"), NOWZ, false); try stor.contSave(&stoz, mkzz("https://x.vn/a-2", "Salon Sao Auto", "0912 345 678", "dealer"), NOWZ, false); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM cont WHERE kind='private' AND name='' AND phon='' AND mail='' AND addr='' AND desc='' AND length(phsh)=17;")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM cont WHERE kind='dealer' AND name='Salon Sao Auto' AND phon='0912345678';")); }
test "forget by phone or id removes the contact and the phone from car rows; drop private keeps dealers" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var dbzz = try opnz(&tmpz, &buff); defer dbzz.close(); var stoz = try cstr.storOpen(&dbzz, NOWZ); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); for ([_][]const u8{ "https://x.vn/a-1", "https://x.vn/a-2", "https://x.vn/a-3" }) |urlz| _ = try cstr.carzSave(&stoz, mkzz(urlz, "", "0966353678", ""), "h", NOWZ); try stor.contSave(&stoz, mkzz("https://x.vn/a-1", "Lê Văn A", "0966353678", "private"), NOWZ, true); try stor.contSave(&stoz, mkzz("https://x.vn/a-2", "Binh", "0911000111", "private"), NOWZ, true); try stor.contSave(&stoz, mkzz("https://x.vn/a-3", "Salon Hai Auto", "0933222111", "dealer"), NOWZ, true); try std.testing.expectEqual(@as(u32, 1), try stor.contForg(&stoz, aren.allocator(), "0966 353 678")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM cont;")); try std.testing.expectEqual(@as(i64, 0), try scal(&dbzz, "SELECT count(*) FROM carz WHERE phon='0966353678';")); try std.testing.expectEqual(@as(u32, 0), try stor.contForg(&stoz, aren.allocator(), "nobody")); try std.testing.expectEqual(@as(u32, 1), try stor.contDrop(&stoz, aren.allocator())); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM cont WHERE kind='dealer';")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM cont;")); }
test "export: vCard escapes commas and newlines, CSV quotes and neutralizes formulas, JSONL reloads into an empty db" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var dbzz = try opnz(&tmpz, &buff); defer dbzz.close(); var stoz = try cstr.storOpen(&dbzz, NOWZ); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); var carz = mkzz("https://x.vn/a-1", "Salon A, B; \"C\"", "0966353678", "dealer"); carz.cdes = "=SUM(1,2)\nline2"; _ = try cstr.carzSave(&stoz, carz, "h", NOWZ); try stor.contSave(&stoz, carz, NOWZ, true);
    const vcfz = try stor.vcrdBuil(allo, &dbzz); try std.testing.expect(std.mem.indexOf(u8, vcfz, "BEGIN:VCARD\r\nVERSION:4.0\r\nFN:Salon A\\, B\\; \"C\"\r\n") != null); try std.testing.expect(std.mem.indexOf(u8, vcfz, "TEL;TYPE=cell:0966353678") != null); try std.testing.expect(std.mem.indexOf(u8, vcfz, "NOTE:=SUM(1\\,2)\\nline2") != null); try std.testing.expect(std.mem.indexOf(u8, vcfz, "ADR:;;1 Phố Huế\\, Hà Nội;Hà Nội;;;VN") != null);
    const csvz = try stor.csvzBuil(allo, &dbzz); try std.testing.expect(std.mem.startsWith(u8, csvz, "cidz,kind,name,phon,pho2,mail,addr,prov,desc,mask,site,urlz,nlis\n")); try std.testing.expect(std.mem.indexOf(u8, csvz, "\"'=SUM(1,2) line2\"") != null); try std.testing.expect(std.mem.indexOf(u8, csvz, "\"Salon A, B; \"\"C\"\"\"") != null); try std.testing.expect(std.mem.endsWith(u8, csvz, ",1\n"));
    const jslz = try stor.rowsBuil(allo, &dbzz); var tmp2 = std.testing.tmpDir(.{}); defer tmp2.cleanup(); var bu2: [160]u8 = undefined; var dbz2 = try opnz(&tmp2, &bu2); defer dbz2.close(); try std.testing.expectEqual(@as(u32, 1), try stor.rowsLoad(&dbz2, allo, jslz)); const jsl2 = try stor.rowsBuil(allo, &dbz2); try std.testing.expectEqualStrings(jslz, jsl2); }
